  font: 700 14px/1.2 'Inter', sans-serif;
  color: #0f172a;
  margin-bottom: 6px;
}
._eli3_vh_empty_desc {
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #64748b;
  max-width: 360px;
  margin: 0 auto;
}

/* Timeline node */
._eli3_vh_node {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #1565c0;
  padding: 10px 12px;
  display: flex; flex-direction: column;
  gap: 8px;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._eli3_vh_node:hover {
  border-color: #cbd5e1;
  border-left-color: #0d47a1;
  box-shadow: 0 2px 6px rgba(15, 23, 42, 0.06);
}
._eli3_vh_node_head {
  display: flex; justify-content: space-between; align-items: flex-start;
  gap: 8px;
}
._eli3_vh_node_main { flex: 1; min-width: 0; }
._eli3_vh_node_title {
  font: 800 12px/1.3 'Inter', sans-serif;
  color: #1565c0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
._eli3_vh_node_num {
  color: #64748b;
  margin-right: 4px;
}
._eli3_vh_node_date {
  font: 500 10px/1.3 'JetBrains Mono', monospace;
  color: #94a3b8;
  margin-top: 3px;
}
._eli3_vh_badge_current {
  display: inline-block;
  background: #e3f2fd;
  color: #1565c0;
  font: 800 9px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  padding: 3px 6px;
  margin-left: 6px;
  vertical-align: 1px;
  border: 1px solid #93c5fd;
}
._eli3_vh_del {
  flex: 0 0 auto;
  background: transparent;
  border: none;
  cursor: pointer;
  font-size: 14px;
  padding: 4px 8px;
  color: #64748b;
  transition: color 0.15s;
}
._eli3_vh_del:hover { color: #c62828; }

._eli3_vh_node_actions {
  display: flex; gap: 6px;
}
._eli3_vh_node_actions button {
  flex: 1;
  padding: 6px 10px;
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_vh_view {
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  color: #475569;
}
._eli3_vh_view:hover {
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  color: #0f172a;
  border-color: #94a3b8;
}
._eli3_vh_compare {
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  box-shadow: 0 1px 3px rgba(21, 101, 192, 0.25);
}
._eli3_vh_compare:hover {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%);
  transform: translateY(-1px);
  box-shadow: 0 3px 8px rgba(21, 101, 192, 0.35);
}

/* Capture-label dialog choices */
._eli3_vh_choice_grid {
  display: flex; flex-direction: column;
  gap: 6px;
  margin: 8px 0;
}
._eli3_vh_choice {
  text-align: left;
  padding: 10px 12px;
  font: 700 12px/1.3 'Inter', sans-serif;
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  color: #0f172a;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_vh_choice:hover {
  background: linear-gradient(180deg, #fff 0%, #e3f2fd 100%);
  border-color: #1565c0;
  color: #0d47a1;
}

/* Preview modal */
._eli3_vh_preview_modal {
  position: fixed;
  top: 60px; left: 30px;
  width: 500px; height: 600px;
  background: #fff;
  display: flex; flex-direction: column;
  box-shadow: 0 15px 50px rgba(0, 0, 0, 0.3);
  border: 1px solid #455a64;
  z-index: 99999;
  resize: both;
  overflow: hidden;
  min-width: 300px;
  min-height: 200px;
}
._eli3_vh_preview_header {
  flex: 0 0 auto;
  padding: 10px 15px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  display: flex; justify-content: space-between; align-items: center;
  border-bottom: 3px solid #c9a227;
  cursor: move;
  user-select: none;
}
._eli3_vh_preview_title {
  font: 700 12px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  pointer-events: none;
}
._eli3_vh_preview_close {
  background: none;
  border: none;
  color: #cbd5e1;
  font-size: 16px;
  cursor: pointer;
  font-weight: 700;
  padding: 0 4px;
}
._eli3_vh_preview_close:hover { color: #f2d866; }
._eli3_vh_preview_frame {
  flex: 1 1 auto;
  border: none;
  width: 100%;
  background: #f5f5f5;
}
